from contextlib import contextmanager
import threading

class Counter:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self.total = 0

    @contextmanager
    def _guard(self):
        with self._lock:
            self._lock.release()
            try:
                yield
            finally:
                self._lock.acquire()

    def add(self, n: int) -> int:
        with self._guard():
            self.total += n
            return self.total

